INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (40, 'CoreAppDb.yml', 'DEFAULT_GROUP', 'spring:\n  jpa:\n    hibernate:\n      ddl-auto: update\n    show-sql: true\n    generate-ddl: true\n    database: mysql\n  datasource:\n    driver-class-name: com.p6spy.engine.spy.P6SpyDriver\n    url: jdbc:p6spy:mysql://192.168.80.32:3306/core_app?serverTimezone=Asia/Shanghai&characterEncoding=UTF-8&useUnicode=true&allowMultiQueries=true\n    username: root\n    password: 123456789\n    type: com.zaxxer.hikari.HikariDataSource\n    hikari:\n      # 连接池名称\n      pool-name: HikariCP\n      # 最小空闲连接数\n      minimum-idle: 5\n      # 最大连接数\n      maximum-pool-size: 20\n      # 连接超时时间(毫秒)\n      connection-timeout: 30000\n      # 空闲连接超时时间(毫秒)\n      idle-timeout: 600000\n      # 连接最大存活时间(毫秒)\n      max-lifetime: 1800000\n      # 连接测试查询\n      connection-test-query: SELECT 1\nmybatis:\n  configuration:\n    map-underscore-to-camel-case: true\n', '371a067fc5c42747e4e68590e46e4a52', '2026-08-10 17:17:18', '2026-08-10 17:17:18', NULL, '192.168.10.48', '', '', NULL, NULL, NULL, 'yaml', NULL, '');
