INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (43, 'com.tbs.shared.pojo.criteria.CommonSystemCompanyQueryCriteria', 'SQL-QUERY', 'SELECT *\nFROM (SELECT d.*,\n             CASE WHEN n.parent_id IS NULL THEN 1 ELSE 0 END AS tree_root_flag\n      FROM sys_company d\n               LEFT JOIN tree_node n ON n.entity_id = d.id AND n.group_name = \'COMPANY_TREE\') AS temp1  ', '17c8d212aae8c40967129e4c1802c439', '2026-08-11 13:50:16', '2026-08-11 14:01:41', NULL, '192.168.10.48', '', '', '', '', '', 'text', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (44, 'com.tbs.shared.pojo.criteria.CommonSystemDepartmentQueryCriteria', 'SQL-QUERY', 'select *\nfrom (SELECT d.*,\n             CASE\n                 WHEN n.parent_id IS NULL THEN\n                     1\n                 ELSE\n                     0\n                 END AS tree_root_flag\n      FROM sys_department d\n               LEFT JOIN tree_node n ON n.entity_id = d.id\n          AND n.group_name = \'DEPARTMENT_TREE\') AS temp\n', '1a3679528826ba86f7a025b49c33466a', '2026-08-11 14:03:28', '2026-08-11 14:03:53', NULL, '192.168.10.48', '', '', '', '', '', 'text', '', '');
